/**
 * The effects engine (src/fx/engine.ts, compiled to dist/fx/engine.js) as a
 * string lib/codegen.mjs can inline into froam.runtime.js — the file a live
 * site loads. A module rather than a file read at save time, so it works the
 * same from the CLI, the Vite plugin and the bundled server.cjs.
 *
 * Runs in `npm run build`, after tsc. The output is committed: lib/ ships.
 */
import fs from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { transformSync } from 'esbuild'

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)))
const compiled = fs.readFileSync(path.join(ROOT, 'dist', 'fx', 'engine.js'), 'utf8')
// A plain script inside the runtime's own function: no module syntax, no source map comment.
const source = compiled
  .replace(/^export /gm, '')
  .replace(/^\/\/# sourceMappingURL=.*$/m, '')
  .trim()
if (/\bimport\b[^(]/.test(source)) throw new Error('build-fx: the effects engine must not import anything')
// It starts itself; minified, since every visitor of a site with effects downloads it.
const { code } = transformSync(`${source}\ninstallFroamFx(window);`, { minify: true, format: 'iife', target: 'es2020' })

const out = path.join(ROOT, 'lib', 'fx-engine-source.mjs')
fs.writeFileSync(out, `// Generated by scripts/build-fx.mjs from src/fx/engine.ts — do not edit.\nexport const FX_ENGINE_SOURCE = ${JSON.stringify(code.trim())}\n`)
console.log(`build-fx: ${path.relative(ROOT, out)} (${(code.length / 1024).toFixed(1)} KB minified)`)
